BEGIN TRANSACTION;
CREATE TABLE "affiliations" (
"work_id" TEXT,
  "author_order" TEXT,
  "institution_id" TEXT
);
CREATE TABLE "authors" (
"author_id" TEXT,
  "name" TEXT,
  "orcid" TEXT
);
CREATE TABLE "authorships" (
"work_id" TEXT,
  "author_order" TEXT,
  "author_position" TEXT,
  "author_id" TEXT,
  "author_name" TEXT,
  "orcid" TEXT,
  "is_corresponding" TEXT
);
CREATE TABLE "citations" (
"citing_work_id" TEXT,
  "cited_work_id" TEXT
);
CREATE TABLE "institutions" (
"institution_id" TEXT,
  "name" TEXT,
  "country_code" TEXT,
  "type" TEXT
);
CREATE TABLE "sources" (
"source_id" TEXT,
  "name" TEXT,
  "issn_l" TEXT,
  "type" TEXT,
  "publisher" TEXT
);
CREATE TABLE "topics" (
"topic_id" TEXT,
  "name" TEXT,
  "subfield" TEXT,
  "field" TEXT,
  "domain" TEXT
);
CREATE TABLE "works" (
"work_id" TEXT,
  "doi" TEXT,
  "title" TEXT,
  "publication_year" TEXT,
  "publication_date" TEXT,
  "type" TEXT,
  "language" TEXT,
  "source_id" TEXT,
  "topic_id" TEXT,
  "is_oa" TEXT,
  "is_retracted" TEXT
);
COMMIT;
